  app.get("/workspace/code/:workspaceId", { preHandler: auth }, async (request) => { const workspace = store.requireWorkspace(workspaceParam.parse(request.params).workspaceId); if (!workspace.members.includes(request.user.sub)) throw new Error("권한이 없습니다"); return ok("초대 코드 조회 성공", workspace.code); });
  app.get("/workspace/search/:code", { preHandler: auth }, async (request) => { const workspace = [...store.workspaces.values()].find((item) => item.code === z.object({ code: z.string() }).parse(request.params).code); if (!workspace) throw new Error("WORKSPACE_NOT_FOUND"); const summary = legacyWorkspace(workspace); return ok("워크스페이스 검색 성공", { workspaceId: summary.workspaceId, workspaceName: summary.workspaceName, workspaceImageUrl: summary.workspaceImageUrl, studentCount: summary.student.length, teacherCount: summary.teacher.length + summary.middleAdmin.length + 1 }); });
