  const waitlistMemberInput = z.object({ workspaceId: z.string().uuid(), memberId: z.string().uuid().optional(), memberIds: z.array(z.string().uuid()).default([]), userSet: z.array(z.string().uuid()).default([]), role: z.enum(["STUDENT", "TEACHER", "MIDDLE_ADMIN"]).default("STUDENT") });
  app.patch("/workspace/add", { preHandler: auth }, async (request) => { const input = body(waitlistMemberInput, request); const workspace = store.requireWorkspace(input.workspaceId); if (!canApproveRole(workspace, request.user.sub, input.role)) throw new Error("권한이 없습니다"); const memberIds = [...new Set([...(input.memberId ? [input.memberId] : []), ...input.memberIds, ...input.userSet])]; if (!memberIds.length) throw new Error("MEMBER_NOT_FOUND"); for (const memberId of memberIds) { if (store.waitlistRoles.get(`${workspace.id}:${memberId}`) !== input.role && workspace.waitlist.includes(memberId)) continue; workspace.waitlist = workspace.waitlist.filter((id) => id !== memberId); store.waitlistRoles.delete(`${workspace.id}:${memberId}`); if (!workspace.members.includes(memberId)) workspace.members.push(memberId); const member = store.requireMember(memberId); const previous = store.profiles.get(`${workspace.id}:${memberId}`); store.profiles.set(`${workspace.id}:${memberId}`, { ...member, workspaceId: workspace.id, ...previous, role: input.role }); void push.send(workspacePushTokens(workspace, [memberId]), { title: workspace.name, body: "워크스페이스 가입이 승인되었습니다.", imageUrl: workspace.image }).catch((error) => app.log.error(error, "FCM workspace push failed")); } return ok("가입 승인 성공"); });
  const memberWorkspaceInput = z.object({ workspaceId: z.string().uuid(), memberId: z.string().uuid() });
